+import XCTest
+@testable import CostCore
+
+final class SplitPropertyTests: XCTestCase {
+    func testDeterministicSplitProperties() {
+        var state: UInt64 = 0xC0DEC0DE
+        func next(_ upper: Int) -> Int { state = state &* 6364136223846793005 &+ 1442695040888963407; return Int((state >> 32) % UInt64(upper)) }
+        for _ in 0..<1000 {
+            let total = Int64(next(10000)), people = next(8) + 1
+            for rule in [SplitRule.everyone, .passengersOnly] {
+                if rule == .passengersOnly && people == 1 { continue }
+                let a = SplitEngine.split(total: MoneyCents(total), people: people, rule: rule)
+                let b = SplitEngine.split(total: MoneyCents(total), people: people, rule: rule)
+                XCTAssertEqual(a, b)
+                XCTAssertEqual(a.shares.reduce(Int64(0)) { $0 + $1.value }, total)
+                XCTAssertTrue(a.shares.allSatisfy { $0.value >= 0 })
+                if rule == .passengersOnly { XCTAssertEqual(a.shares[0], .zero) }
+            }
+        }
+    }
+
+    func testRemainderCanMakeDriverShareDecrease() {
+        XCTAssertGreaterThan(SplitEngine.split(total: MoneyCents(399), people: 4, rule: .everyone).shares[0].value,
+                             SplitEngine.split(total: MoneyCents(400), people: 4, rule: .everyone).shares[0].value)
+    }
+}

